    /// <summary>
    /// table modified field method
    /// </summary>
    /// <param name = "_fieldId">field Id</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(METCSDCustPickingsequence, CustAccount):
                this.CustName = DirPartyTable::getName(CustTable::find(this.CustAccount).Party);
                break;
        }
    }

    /// <summary>
    /// CSD customer picking sequence find method
    /// </summary>
    /// <param name = "_inventLocationId">Warehouse</param>
    /// <param name = "_lineNum">Line Num</param>
    /// <param name = "_update">updated buffer</param>
    /// <returns>METCSDCustPickingSequence table buffer</returns>
    static METCSDCustPickingSequence find(InventLocationId _inventLocationId,
                                          LineNum          _lineNum,
                                          boolean          _update = false)
    {
        METCSDCustPickingSequence   custPickingSequence;

        if (_inventLocationId)
        {
            if (_update)
            {
                custPickingSequence.selectForUpdate(_update);
            }
            if (_lineNum)
            {
                select firstonly custPickingSequence
                    index hint SeqNumIdx
                    where custPickingSequence.InventLocationId  == _inventLocationId
                    &&    custPickingSequence.SequenceNumber  == _lineNum;
            }
        }

        return custPickingSequence;
    }

    /// <summary>
    /// Check if record exists
    /// </summary>
    /// <param name = "_inventLocationId">Warehouse</param>
    /// <param name = "_lineNum">Line Num</param>
    /// <returns>true or false</returns>
    static boolean exist(InventLocationId _inventLocationId,
                         LineNum          _lineNum)
    {
        if (!_inventLocationId && !_lineNum)
        {
            return false;
        }

        return (select firstonly RecId from METCSDCustPickingSequence
                    index hint SeqNumIdx
                    where METCSDCustPickingSequence.InventLocationId  == _inventLocationId
                    &&    METCSDCustPickingSequence.SequenceNumber  == _lineNum).RecId != 0;
    }

/// <summary>
/// Find the next unique LineCreationSequenceNumber per inventlocationId.
/// </summary>
/// <param name = "_inventLocationId">warehouse Id</param>
/// <returns>Next unique LineCreationSequenceNumber</returns>
static METWaveSeqNum LastCustPickingSequenceNum(InventLocationId _inventLocationId)
{
    return (select maxof(SequenceNumber) from metCSDCustPickingSequence
                index hint SeqNumIdx
                where metCSDCustPickingSequence.InventLocationId == _inventLocationId).SequenceNumber;
}
